{
  "programs": {
    "q0": {
      "code": "sheet = 'W0::cpsaat14'\n# TOTAL row for Total, 16 years and over is row 8.\n# But wait, let's find the TOTAL row for age groups across all industries (col A = 'TOTAL', then age rows).\n# Let's inspect rows for TOTAL section:\n# A7: 'TOTAL'\n# A8: 'Total, 16 years and over'\n# A9: '16 to 19 years'\n# A11: '20 to 24 years'\n# The question asks: 'How many more employed people were aged 20 to 24 than aged 16 to 19 across all industries?'\n# Across all industries means the TOTAL column (col B through M summed, or the TOTAL row values).\n# Let's sum across all columns (B to M) for row 11 (20 to 24 years) and row 9 (16 to 19 years).\nrow_20_24 = sum(num(sheet, f'{c}11') for c in ['B','C','D','E','F','G','H','I','J','K','L','M'] if num(sheet, f'{c}11') is not None)\nrow_16_19 = sum(num(sheet, f'{c}9') for c in ['B','C','D','E','F','G','H','I','J','K','L','M'] if num(sheet, f'{c}9') is not None)\nresult = int(row_20_24 - row_16_19)",
      "result_variable": "result",
      "format": {
        "kind": "integer",
        "decimals": null,
        "count": null,
        "separator": ""
      },
      "assumptions": [],
      "needs_verification": false
    }
  }
}
